import numpy as np


class KappaCalculator:

    @staticmethod
    def kappa(test_data, k):
        """
        Calculate Cohen's Kappa coefficient for categorical data.

        Args:
            test_data: 2D array-like of shape (k, k) representing the confusion matrix
            k: number of categories

        Returns:
            Cohen's Kappa coefficient
        """
        data_mat = np.mat(test_data)
        observed_agreement = KappaCalculator._sum_diagonal(data_mat, k)
        expected_agreement = KappaCalculator._calculate_expected_agreement(data_mat)
        return KappaCalculator._compute_kappa(observed_agreement, expected_agreement)

    @staticmethod
    def _sum_diagonal(data_mat, k):
        """Sum the diagonal elements of the confusion matrix."""
        return np.sum(data_mat.diagonal())

    @staticmethod
    def _calculate_expected_agreement(data_mat):
        """Calculate the expected agreement probability."""
        row_sums = np.sum(data_mat, axis=1)
        col_sums = np.sum(data_mat, axis=0)
        total = np.sum(data_mat)
        if total == 0:
            return 0.0
        return float(np.dot(col_sums, row_sums) / (total * total))

    @staticmethod
    def _compute_kappa(observed_agreement, expected_agreement):
        """Compute kappa coefficient from observed and expected agreement."""
        if expected_agreement == 1:
            return 0.0
        return float((observed_agreement - expected_agreement) / (1 - expected_agreement))

    @staticmethod
    def fleiss_kappa(test_data, n_annotators, k_categories, n_samples):
        """
        Calculate Fleiss' Kappa for multi-annotator data.

        Args:
            test_data: 2D array-like of shape (N, k) where N is number of subjects 
                      and k is number of categories
            n_annotators: number of annotators per subject
            k_categories: number of categories
            n_samples: alias for n_annotators (kept for backward compatibility)

        Returns:
            Fleiss' Kappa coefficient
        """
        data_mat = np.mat(test_data, dtype=float)
        observed_agreement = KappaCalculator._calculate_fleiss_observed_agreement(
            data_mat, n_samples, k_categories
        )
        expected_agreement = KappaCalculator._calculate_fleiss_expected_agreement(
            data_mat, k_categories
        )
        return KappaCalculator._compute_kappa(observed_agreement, expected_agreement)

    @staticmethod
    def _calculate_fleiss_observed_agreement(data_mat, n_annotators, k_categories):
        """Compute observed agreement for Fleiss' Kappa."""
        total_counts = np.sum(data_mat)
        if total_counts == 0:
            return 0.0

        n_samples = n_annotators
        # Sum of squared ratings per subject, adjusted
        sum_sq_ratings = np.sum(data_mat ** 2, axis=1)
        # For each subject i: (sum_j^2 - n) / (n * (n-1))
        per_subject = (sum_sq_ratings - n_samples) / (n_samples * (n_samples - 1))
        observed = np.sum(per_subject) / len(per_subject)
        return float(observed)

    @staticmethod
    def _calculate_fleiss_expected_agreement(data_mat, k_categories):
        """Compute expected agreement for Fleiss' Kappa."""
        total_counts = np.sum(data_mat)
        if total_counts == 0:
            return 0.0
        # Marginal proportions squared and summed
        marginal_sums = np.sum(data_mat, axis=0)
        proportions = marginal_sums / total_counts
        expected = np.sum(proportions ** 2)
        return float(expected)
